import json
import time
import threading
from collections import defaultdict, deque

HOST = "127.0.0.1"
PORT = 8000
MAX_PER_WINDOW = 5
WINDOW_MS = 60000

# Track per-client request timestamps
_rate_limits = defaultdict(deque)
_lock = threading.Lock()


def check_rate_limit(ip):
    """Returns (allowed, retry_after)."""
    now = time.monotonic()
    window_ms = WINDOW_MS
    max_per = MAX_PER_WINDOW
    with _lock:
        timestamps = _rate_limits[ip]
        # Prune timestamps outside the window
        cutoff = now - window_ms / 1000.0
        while timestamps and timestamps[0] < cutoff:
            timestamps.popleft()
        if len(timestamps) >= max_per:
            oldest = timestamps[0]
            retry_after = oldest + window_ms / 1000.0 - now
            return False, retry_after
        # Allowed
        timestamps.append(now)
        return True, 0.0


class RateLimitedHandler(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == "/api/time":
            allowed, retry_after = check_rate_limit(self.client_address[0])
            if not allowed:
                self.send_response(429)
                self.send_header("Retry-After", str(retry_after))
                self.send_header("Content-Type", "application/json")
                self.send_header("Access-Control-Allow-Origin", "*")
                self.end_headers()
                self.wfile.write(json.dumps({"error": "rate limited"}).encode())
                return
            now = int(time.time())
            body = json.dumps({"now": now}).encode()
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            self.wfile.write(body)
        else:
            self.send_response(404)
            self.end_headers()

    def log_message(self, format, *args):
        # Quiet logging or keep it
        pass


def main():
