export interface ThrottleOptions {
  maxPerWindow: number;
  windowMs: number;
}

/**
 * Returns a throttled wrapper around `fn`.
 *
 * `fn` is called at most `maxPerWindow` times within each `windowMs` window.
 * Any extra calls are silently skipped.
 */
export function throttle<T extends (...args: any[]) => void>(
  fn: T,
  maxPerWindow: number,
  windowMs: number
): (...args: Parameters<T>) => void {
  let lastCall = 0;
  let count = 0;
  let timer: ReturnType<typeof setTimeout> | null = null;

  const now = (): number => Date.now();
  const toMs = (sec: number): number => Math.max(0, Math.round(sec * 1000));

  return (...args: Parameters<T>): void => {
    const current = now();
    const elapsedSec = (current - lastCall) / 1000;

    // If the window has elapsed, start a fresh window.
    if (elapsedSec >= windowMs / 1000) {
      lastCall = current;
      count = 0;
    }

    // Skip if we've already called fn maxPerWindow times in this window.
    if (count >= maxPerWindow) {
      return;
    }

    count++;
    lastCall = current;
    fn(...args);

    // Schedule the next allowed call for this window.
    if (count < maxPerWindow) {
      const remainingSec = windowMs / 1000 - elapsedSec;
      timer = setTimeout(() => {
        timer = null;
        count = 0;
        lastCall = now();
      }, toMs(remainingSec));
    }
  };
}
